    if not coords:
        return grid

    min_r = min(r for r, c in coords)
    max_r = max(r for r, c in coords)
    min_c = min(c for r, c in coords)
    max_c = max(c for r, c in coords)

    result = [row[:] for row in grid]

    # Find actual gaps on perimeter (where frame is missing)
    left_gaps = [r for r in range(min_r, max_r + 1) if grid[r][min_c] != 8]
    right_gaps = [r for r in range(min_r, max_r + 1) if grid[r][max_c] != 8]
    top_gaps = [c for c in range(min_c, max_c + 1) if grid[min_r][c] != 8]
    bottom_gaps = [c for c in range(min_c, max_c + 1) if grid[max_r][c] != 8]

    # The pattern: 2s appear where a diagonal line from a corner passes through
    # a background cell adjacent to (at same row or column as) a gap position

    corners = [(min_r, min_c), (min_r, max_c), (max_r, min_c), (max_r, max_c)]

    for r in range(min_r + 1, max_r):
